    assert client.post(f"/api/sessions/{sid}/text-turns", json={"text": "x" * 2001}).status_code == 400
    assert client.delete(f"/api/sessions/{sid}").status_code == 200
    assert client.get(f"/api/sessions/{sid}").status_code == 404


